(8798,'%project_name a été ajouté/mis à jour avec succès','fr',0),
(8799,'Voir les adresses électroniques des utilisateurs','fr',0),
(8800,'Les utilisateurs qui ne disposent pas de cette permission n\'auront pas accès aux adresses de courriel sur les pages des utilisateurs ou sur d\'autres pages sur lesquelles elles pourraient être affichées, comme dans des Vues ou des réponses JSON:API.','fr',0),
(8801,'Le nom d\'utilisateur ou l\'adresse de courriel n\'est pas valide.','fr',0),
(8802,'Le formulaire de réinitialisation du mot de passe a été soumis avec un compte inconnu ou inactif : %name.','fr',0),
(8803,'Toujours présenter l\'affichage par défaut','fr',0),
(8804,'Publier l\'espace de travail','fr',0),
(8805,'Publier l\'espace de travail %source_label','fr',0),
