INSERT INTO `locales_target` VALUES
(11674,'Le type de Paragraphe %type est utilisé par 1 élément de contenu sur votre site. Vous ne pouvez pas supprimer le type de Paragraphe %type tant qu\'il n\'aura pas été retiré de tous les contenus.Le type de Paragraphe %type est utilisé par @count éléments de contenu sur votre site. Vous ne pouvez pas supprimer le type de Paragraphe %type tant qu\'il n\'aura pas été retiré de tous les contenus.','fr',0),
