INSERT INTO `search_dataset` VALUES
(1,'fr','help_search',' affichage des annonces de drupal que sont les annonces de drupal  un flux d annonces a propos du projet drupal et des programmes de la drupal association le but de ce flux est de fournir un moyen de communication directe vers les proprietaires de sites drupal le contenu remonte est concu pour etre tres pertinent pour les proprietaires de sites servir les objectifs strategiques du projet et ou promouvoir la perennite du projet et de l association drupal le module extrait son contenu d un flux json genere a partir de cette page  la politique de gouvernance du contenu est documentee sur cette page  comment voir les annonces sur mon site  si le module toolbar est active un lien direct se trouve dans la barre d outils pour y acceder si le module toolbar n est pas active le contenu peut toujours etre consulte sur la page annonces  qui peut voir les annonces  les utilisateurs ayant la permission voir les annonces officielles liees a drupal peuvent consulter les annonces de drupalorg ressources supplementaires vue d ensemble du module announcement ',1755170361),
(2,'fr','help_search',' configurer un bloc deja place objectif configurer les parametres d un bloc qui etait place dans une region d un theme etapes dans le menu d administration gerer  cliquer sur structure   mise en page des blocs  cliquer sur le nom du theme contenant le bloc optionnellement selectionner montrer les regions pour visualiser les regions du theme si vous souhaitez simplement changer la region dans laquelle se trouve un bloc ou reordonner les blocs a l interieur d une region faites glisser les blocs a la position souhaitee et cliquez sur enregistrer les blocs  si vous souhaitez modifier d autres parametres trouver la region dans laquelle se situe le bloc que vous voulez mettre a jour et cliquer sur configurer dans la ligne de description du bloc modifier les parametres du bloc les parametres disponibles varient selon le module qui fournit le bloc mais pour tous les blocs vous pouvez changer  titre du bloc  l entete de ce bloc sur votre site pour certains blocs vous devrez cocher la case surcharger le titre afin de pouvoir saisir un titre afficher le titre  cocher la case pour afficher le titre visibilite  ajouter des conditions d affichage du bloc region  modifier la region du theme dans laquelle le bloc est affiche cliquer enregistrer le bloc   ',1755187506),
(3,'fr','help_search',' placer un bloc objectif positionner un bloc dans une region du theme etapes dans le menu d administration gerer  cliquer sur structure  mise en page des blocs cliquer sur le nom du theme dans lequel vous voulez placer le bloc optionnellement selectionner montrer les regions pour visualiser les regions du theme reperer la region dans laquelle vous souhaitez placer le bloc et cliquer sur placer le bloc dans cette region une fenetre modale s ouvrira reperer le bloc que vous souhaitez placer et cliquer sur placer le bloc  une fenetre modale configurer le bloc s ouvrira configurer le bloc et cliquer sur enregistrer le bloc  consulter configurer un bloc deja place pour avoir des details sur la configuration  ',1755187506),
(4,'fr','help_search',' gerer les blocs que sont les blocs  les blocs sont des boites de contenu rendues dans une zone ou region d une page web de votre site les blocs sont positionnes et configures de maniere specifique pour chaque theme que sont les blocs de contenu  les blocs de contenu sont des blocs dont vous pouvez modifier le contenu vous pouvez definir un ou plusieurs types de bloc et y attacher des champs vous pouvez positionner les blocs de contenu dans des regions a l instar des blocs issus des autres modules qu estce que la description du bloc  la description du bloc permet d identifier un bloc elle est affichee dans l interface d administration mais pas sur le site qu estce que le titre du bloc  le titre du bloc est le titre qui est potentiellement affiche aux visiteurs du site lorsque le bloc est place dans une region vue d ensemble pour la gestion des blocs le module block vous permet de placer des blocs dans les regions de vos themes installes et de configurer les parametres des blocs le module block content vous permet de gerer les types de bloc et les blocs de contenu consulter les sujets lies listes cidessous pour les taches specifiques ressources supplementaires blocs guide utilisateur drupal  ',1755187506),
